#!/usr/bin/env python3
import csv,gzip,hashlib,io,json,os,re,time,urllib.error,urllib.parse,urllib.request,base64
from collections import Counter
from datetime import datetime,timezone
from pathlib import Path
BASE='https://api.iucnredlist.org/api/v4'; N=2742; QSHA='901f748d8733dfb85cb566bbc0308274248718bd98fb10c72721fbdd415685ed'
QB64=''''''
OUT=Path(os.environ.get('IUCN_OUT','artifacts/iucn_all_2742_fresh')); WAIT=float(os.environ.get('IUCN_WAIT_SECONDS','0.65')); TOKEN=os.environ.get('IUCN_API_TOKEN','').strip(); LAST=0.0

def now(): return datetime.now(timezone.utc).isoformat()
def norm(s): return re.sub(r'\s+',' ',(s or '').strip()).casefold()
def sha(obj): return hashlib.sha256(json.dumps(obj,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
def qrows():
    data=gzip.decompress(base64.b64decode(QB64)); got=hashlib.sha256(data).hexdigest()
    if got!=QSHA: raise SystemExit(f'QUEUE_SHA_MISMATCH {got}')
    rows=list(csv.DictReader(io.StringIO(data.decode('utf-8'))))
    if len(rows)!=N: raise SystemExit(f'QUEUE_COUNT_MISMATCH {len(rows)}')
    return data,rows

def throttle():
    global LAST
    d=time.monotonic()-LAST
    if d<WAIT: time.sleep(WAIT-d)

def get(endpoint):
    global LAST
    if not TOKEN: raise SystemExit('IUCN_API_TOKEN missing')
    url=endpoint if endpoint.startswith('http') else BASE+'/'+endpoint.lstrip('/')
    for a in range(6):
        throttle(); req=urllib.request.Request(url,headers={'Authorization':TOKEN,'Accept':'application/json','User-Agent':'JBLR-STIMES-IUCN/1.0'})
        try:
            with urllib.request.urlopen(req,timeout=60) as r:
                LAST=time.monotonic(); return json.loads(r.read().decode()),r.status,url
        except urllib.error.HTTPError as e:
            LAST=time.monotonic(); body=e.read().decode('utf-8','replace')
            if e.code==404: return {'_http_error':404,'_body':body[:1000]},404,url
            if (e.code==429 or 500<=e.code<600) and a<5:
                ra=e.headers.get('Retry-After'); time.sleep(float(ra) if ra and ra.isdigit() else min(30,2**a)); continue
            raise RuntimeError(f'HTTP {e.code} {url}: {body[:500]}')
        except (urllib.error.URLError,TimeoutError) as e:
            LAST=time.monotonic()
            if a<5: time.sleep(min(30,2**a)); continue
            raise RuntimeError(f'NETWORK {url}: {e}')

def binomial(name):
    p=name.replace('×',' x ').split()
    if len(p)<2: return None,None,'UNPARSABLE'
    g,s=p[0],p[1].strip('(),;')
    if not re.match(r'^[A-Za-z][A-Za-z-]+$',g) or not re.match(r'^[a-z][A-Za-z-]+$',s): return None,None,'UNPARSABLE'
    return g,s,'BINOMIAL' if len(p)==2 else 'COMPLEX_OR_INFRASPECIFIC'

def nodes(payload):
    t=payload.get('taxon') if isinstance(payload,dict) else None
    if not isinstance(t,dict): return []
    out=[('PRIMARY',t)]
    for k,l in [('species_taxa','SPECIES_CHILD'),('infrarank_taxa','INFRARANK_CHILD'),('subpopulation_taxa','SUBPOPULATION_CHILD')]:
        out += [(l,x) for x in (t.get(k) or []) if isinstance(x,dict)]
    return out

def match(target,payload):
    n=norm(target)
    for k,x in nodes(payload):
        if norm(x.get('scientific_name'))==n: return 'EXACT_'+k,x
    for k,x in nodes(payload):
        for s in x.get('synonyms') or []:
            if isinstance(s,dict) and norm(s.get('name'))==n: return 'SYNONYM_'+k,x
    return 'NO_EXACT_MATCH',None

def scopes(a):
    z=set()
    for s in a.get('scopes') or []:
        if not isinstance(s,dict): continue
        d=s.get('description'); d=d.get('en') if isinstance(d,dict) else d
        if d: z.add(str(d).casefold())
        if s.get('code') is not None: z.add(str(s.get('code')).casefold())
    return z

def select_global(a):
    c=[x for x in a if isinstance(x,dict) and ('global' in scopes(x) or '1' in scopes(x))]
    if not c: return None
    c2=[x for x in c if x.get('latest') is True] or c
    def key(x):
        try:y=int(x.get('year_published') or 0)
        except:y=0
        try:i=int(x.get('assessment_id') or 0)
        except:i=0
        return y,i
    return max(c2,key=key)

def assessments(ms,node,lookup):
    if not node:return []
    if ms.endswith('PRIMARY'): return lookup.get('assessments') or []
    sid=node.get('sis_id')
    if not sid:return []
    p,s,_=get(f'taxa/sis/{sid}'); return p.get('assessments') or [] if s==200 else []

def main():
    qb,rows=qrows(); OUT.mkdir(parents=True,exist_ok=True); (OUT/'IUCN_ALL_2742_QUEUE_USED.csv').write_bytes(qb)
    res=[]; issues=[]; cnt=Counter(); cats=Counter(); errors=0; started=now(); rawp=OUT/'IUCN_ALL_2742_RAW.jsonl.gz'
    with gzip.open(rawp,'wt',encoding='utf-8') as raw:
      for i,row in enumerate(rows,1):
        t=row['taxon'].strip(); idx=int(row['universe_index']); fam=row['family'].strip(); at=now(); g,s,cx=binomial(t)
        r={'universe_index':idx,'family':fam,'taxon':t,'query_complexity':cx,'match_state':'','matched_scientific_name':'','sis_taxon_id':'','global_assessment_state':'','assessment_id':'','red_list_category_code':'','red_list_category':'','criteria':'','year_published':'','assessment_date':'','latest':'','population_trend_code':'','population_trend':'','possibly_extinct':'','possibly_extinct_in_the_wild':'','iucn_url':'','citation':'','lookup_http_status':'','lookup_url':'','raw_lookup_sha256':'','raw_assessment_sha256':'','source_accessed_at':at,'source':'IUCN_RED_LIST_API_V4_FRESH'}
        ro={'queue':row,'accessed_at':at,'lookup':None,'assessment':None}
        if not g:
            r['match_state']='UNPARSABLE_NAME'; r['global_assessment_state']='NOT_QUERIED_UNPARSABLE'; issues.append({**row,'issue':'UNPARSABLE_NAME','detail':''}); cnt['UNPARSABLE_NAME']+=1; res.append(r); raw.write(json.dumps(ro,ensure_ascii=False)+'\n'); continue
        try:
            lp,hs,lu=get('taxa/scientific_name?'+urllib.parse.urlencode({'genus_name':g,'species_name':s})); ro['lookup']=lp; r['lookup_http_status']=hs; r['lookup_url']=lu; r['raw_lookup_sha256']=sha(lp)
            if hs==404:
                r['match_state']='NO_API_TAXON'; r['global_assessment_state']='NO_API_TAXON'; issues.append({**row,'issue':'NO_API_TAXON','detail':''}); cnt['NO_API_TAXON']+=1
            else:
                ms,node=match(t,lp); r['match_state']=ms; cnt[ms]+=1
                if node: r['matched_scientific_name']=node.get('scientific_name') or ''; r['sis_taxon_id']=node.get('sis_id') or ''
                if ms.startswith('SYNONYM_'): issues.append({**row,'issue':ms,'detail':''})
                if ms=='NO_EXACT_MATCH': r['global_assessment_state']='NO_EXACT_TAXON_MATCH'; issues.append({**row,'issue':'NO_EXACT_TAXON_MATCH','detail':''})
                else:
                    sel=select_global(assessments(ms,node,lp))
                    if not sel: r['global_assessment_state']='NO_GLOBAL_ASSESSMENT_FOUND'; cnt['NO_GLOBAL_ASSESSMENT_FOUND']+=1
                    else:
                        aid=sel.get('assessment_id'); r['assessment_id']=aid or ''; r['year_published']=sel.get('year_published') or ''; r['latest']=sel.get('latest'); r['iucn_url']=sel.get('url') or ''
                        if aid:
                            ap,ahs,_=get(f'assessment/{aid}'); ro['assessment']=ap; r['raw_assessment_sha256']=sha(ap)
                            if ahs==200:
                                cat=ap.get('red_list_category') or {}; desc=cat.get('description'); desc=desc.get('en') if isinstance(desc,dict) else desc; tr=ap.get('population_trend') or {}; td=tr.get('description'); td=td.get('en') if isinstance(td,dict) else td
                                r.update(global_assessment_state='GLOBAL_ASSESSMENT_ACQUIRED',red_list_category_code=cat.get('code') or '',red_list_category=desc or '',criteria=ap.get('criteria') or '',year_published=ap.get('year_published') or r['year_published'],assessment_date=ap.get('assessment_date') or '',latest=ap.get('latest'),population_trend_code=tr.get('code') or '',population_trend=td or '',possibly_extinct=ap.get('possibly_extinct'),possibly_extinct_in_the_wild=ap.get('possibly_extinct_in_the_wild'),iucn_url=ap.get('url') or r['iucn_url'],citation=ap.get('citation') or '')
                                cnt['GLOBAL_ASSESSMENT_ACQUIRED']+=1; cats[str(cat.get('code') or 'UNKNOWN')]+=1
                            else:r['global_assessment_state']=f'ASSESSMENT_HTTP_{ahs}'; issues.append({**row,'issue':r['global_assessment_state'],'detail':''})
                        else:r['global_assessment_state']='ASSESSMENT_ID_MISSING'; issues.append({**row,'issue':'ASSESSMENT_ID_MISSING','detail':''})
            res.append(r)
        except Exception as e:
            errors+=1; r['match_state']=r['match_state'] or 'API_ERROR'; r['global_assessment_state']='API_ERROR'; res.append(r); issues.append({**row,'issue':'API_ERROR','detail':str(e)[:500]}); ro['error']=str(e)[:1000]; cnt['API_ERROR']+=1
        raw.write(json.dumps(ro,ensure_ascii=False)+'\n')
        if i%100==0: print(f'processed={i}/{N} acquired={cnt["GLOBAL_ASSESSMENT_ACQUIRED"]} errors={errors}',flush=True)
    fn=list(res[0]);
    with open(OUT/'IUCN_ALL_2742_RESULTS.csv','w',encoding='utf-8',newline='') as f:w=csv.DictWriter(f,fieldnames=fn);w.writeheader();w.writerows(res)
    with open(OUT/'IUCN_ALL_2742_ISSUES.csv','w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['universe_index','family','taxon','issue','detail'],extrasaction='ignore');w.writeheader();w.writerows(issues)
    qa={'execution':'IUCN_ALL_2742_FRESH_v1','source':'IUCN Red List API v4','started_at':started,'finished_at':now(),'queue_count':len(rows),'queue_sha256':QSHA,'results_count':len(res),'api_errors':errors,'complete':len(res)==N and errors==0,'counts':dict(sorted(cnt.items())),'categories':dict(sorted(cats.items())),'raw_jsonl_gz_sha256':hashlib.sha256(rawp.read_bytes()).hexdigest(),'semantic_guard':'IUCN data are evidence, not automatic STIME conclusions. Synonym, parent and complex-name matches require explicit taxonomic applicability before score mutation.'}
    (OUT/'IUCN_ALL_2742_QA.json').write_text(json.dumps(qa,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); print(json.dumps(qa,ensure_ascii=False,indent=2))
    if errors: raise SystemExit(2)
if __name__=='__main__': main()
